window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[115]={"id":"115","numero":115,"titre":"Toxidermies","objectifs":[{"id":"115-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une toxidermie","contenu":"<table >\n        <thead><tr><th>Item</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Définition</strong></td>\n            <td>Toxidermies = <span class=\"kw-def\">effets cutanés secondaires des médicaments</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Cause</strong></td>\n            <td><strong>Tout médicament</strong> peut être responsable d’une toxidermie ✅, même si certaines molécules sont plus fréquemment en cause que d’autres. <span class=\"kw-alerte\">Ne jamais s’arrêter au « coupable idéal »</span> — tenir compte de <strong>tous</strong> les médicaments potentiellement en cause.</td>\n          </tr>\n          <tr>\n            <td><strong>Cadre réglementaire</strong></td>\n            <td>Toxidermies = <strong>notification obligatoire</strong> aux <strong>instances de pharmacovigilance</strong> (obligation légale 🔥).</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 326 — Bon usage du médicament · 325 — Iatrogénie · 187 — <span class=\"kw-ci\">Hypersensibilité</span> et allergies cutanéomuqueuses</em></p>","frequence":1},{"id":"115-2","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître les différents mécanismes des toxidermies","contenu":"<p>Une toxidermie peut répondre à <strong>plusieurs mécanismes différents</strong> qui peuvent avoir la <strong>même présentation clinique</strong> (ex. <span class=\"kw-clinique\">urticaire</span> et <span class=\"kw-clinique\">photosensibilité</span>).</p>\n\n      <section class=\"lane\">\n        <h4>Mécanisme non immunologique</h4>\n        <ul>\n          <li><strong>Effet pharmacologique</strong> : lié aux effets pharmacodynamiques principaux du médicament (ex. <span class=\"kw-clinique\">xérose</span> et chéilite sous <span class=\"kw-ttt\">rétinoïdes</span>).</li>\n          <li><strong>Effet <span class=\"kw-etio\">toxique</span> / latéral</strong> : conséquence d’un effet autre que l’effet pharmacologique principal recherché (ex. alopécie induite par les <strong>antimitotiques</strong>, pigmentation sous <strong><span class=\"kw-ttt\">hydroxychloroquine</span></strong>).</li>\n        </ul>\n      </section>\n\n      <section class=\"lane\">\n        <h4>Mécanisme immunologique</h4>\n        <ul>\n          <li><strong>IgE médiée</strong> — <span class=\"kw-ci\">hypersensibilité</span> immédiate (rapide après une prise) : <span class=\"kw-clinique\">urticaire</span>, angiœdème, <span class=\"kw-def\">choc anaphylactique</span>. ⚠️ <em>Ces manifestations peuvent aussi être engendrées par des mécanismes non immunologiques.</em></li>\n          <li><strong>Médiée par les <span class=\"kw-bio\">lymphocytes</span></strong> — <span class=\"kw-ci\">hypersensibilité</span> <strong>retardée</strong> (plus <strong>fréquente</strong>), de plusieurs jours à plusieurs semaines après une prise :\n            <ul>\n              <li><span class=\"kw-clinique\">Non graves</span> : toxidermie érythémateuse, <span class=\"kw-clinique\">érythème</span> pigmenté fixe</li>\n              <li><span class=\"kw-alerte\">Graves</span> : <span class=\"kw-alerte\">PEAG</span>, DRESS, Stevens-Johnson, Lyell</li>\n            </ul>\n          </li>\n        </ul>\n      </section>\n\n      <h4>Tableau : caractéristiques selon le mécanisme</h4>\n      <table class=\"matrix\">\n        <thead>\n          <tr><th>Critère</th><th>Non immunologique</th><th>Immunologique</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Mécanisme</strong></td><td>Effet pharmacodynamique</td><td>Immuno-<span class=\"kw-etio\">allergique</span></td></tr>\n          <tr><td><strong>Fréquence</strong></td><td><strong>Élevée</strong></td><td><strong>Rare</strong></td></tr>\n          <tr><td><strong>Dose-dépendant</strong></td><td><strong>Oui</strong></td><td><strong>Non</strong> ❌</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Mortalité</span></strong></td><td>Faible</td><td>Variable</td></tr>\n          <tr><td><strong>Délai de survenue</strong></td><td>Variable</td><td>Plusieurs jours à plusieurs semaines</td></tr>\n          <tr><td><strong>Prévisible</strong></td><td>Oui</td><td>Non</td></tr>\n          <tr><td><strong>Détection</strong></td><td>Essais contrôlés + études post-AMM</td><td>Études post-AMM</td></tr>\n          <tr><td><strong>Mesures réglementaires</strong></td><td>Retrait rare · modification <span class=\"kw-def\">RCP</span></td><td>Retrait possible si <span class=\"kw-alerte\">toxidermie grave</span> · modification <span class=\"kw-def\">RCP</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"115-3","rang":"B","rubrique":"Prévalence/épidémiologie","titre":"Connaître la fréquence de survenue des toxidermies, le type de toxidermie le plus fréquent, le pronostic habituel","contenu":"<table >\n        <thead><tr><th>Item</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Fréquence</strong></td>\n            <td>\n              <ul>\n                <li>Iatrogénie globale : responsable de <strong><span class=\"kw-chiffre\">10 %</span></strong> des hospitalisations.</li>\n                <li>Accidents iatrogènes <span class=\"kw-etio\">médicamenteux</span> (AIM) : <strong><span class=\"kw-chiffre\">0,5–2 %</span></strong> des consultations en médecine ambulatoire.</li>\n                <li><strong>Toxidermies = les AIM les plus fréquents</strong>.</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Pronostic</span></strong></td>\n            <td>\n              <ul>\n                <li>Environ <strong>&gt;<span class=\"kw-chiffre\"> 90 %</span></strong> des toxidermies sont <span class=\"kw-clinique\">bénignes</span>.</li>\n                <li>Les formes mettant en jeu le <span class=\"kw-alerte\">pronostic vital</span> sont trop rares pour être détectées dans les essais précédant l’AMM → <strong>1 cas pour 10 000 à 1 000 000</strong> patients traités.</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Formes les plus fréquentes</strong></td>\n            <td>\n              <ul>\n                <li>Toxidermies érythémateuses (exanthèmes maculo-papuleux) = <strong><span class=\"kw-chiffre\">40–60 %</span></strong> des notifications.</li>\n                <li>Urticaires = <strong><span class=\"kw-chiffre\">20–30 %</span></strong> des notifications.</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>","frequence":1},{"id":"115-4","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître les deux mécanismes de photosensibilité","contenu":"<p><strong><span class=\"kw-clinique\">Photosensibilité</span></strong> = <span class=\"kw-clinique\">éruption</span> survenant dans les heures qui suivent une <span class=\"kw-etio\">exposition solaire</span>, en <strong>photodistribution</strong> (zones découvertes : visage, décolleté, extrémités).</p>\n      <div class=\"callout callout-info\">\n        <strong>Argument fort.</strong> Absence d’ATCD de réaction de <span class=\"kw-clinique\">photosensibilité</span> ❌ = argument fort pour une <strong>cause exogène</strong> (médicaments ou de contact).\n      </div>\n\n      <h4>Photo-<span class=\"kw-ci\">allergie</span> <span class=\"kw-bio\">vs</span> Photo-toxicité</h4>\n      <table class=\"matrix\">\n        <thead>\n          <tr><th>Critère</th><th>Photo-allergie</th><th>Photo-toxicité</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Effet-dose</strong></td>\n            <td>Parfois déclenchée par des expositions <strong>solaires minimes</strong></td>\n            <td>Dépend des <strong>doses de médicament ET des doses d’<span class=\"kw-ttt\">UVA</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>Délai</strong></td>\n            <td><strong><span class=\"kw-chiffre\">7–21 jours</span> après le début</strong> du traitement (voie systémique ou topique)</td>\n            <td>Survient <strong>rapidement</strong>, dans les heures qui suivent l’exposition, et <strong>dès les 1ères prises</strong> médicamenteuses</td>\n          </tr>\n          <tr>\n            <td><strong>Manifestations</strong></td>\n            <td>\n              Lésions d’<strong><span class=\"kw-clinique\">eczéma</span></strong>, extension possible aux zones couvertes.<br>\n              Exceptionnellement, les lésions peuvent persister malgré l’arrêt du médicament.<br>\n              Confirmation par <strong>photo-patchs tests</strong> (patch tests suivis d’une <span class=\"kw-clinique\">irradiation</span> par <span class=\"kw-ttt\">UVA</span>).\n            </td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Érythème</span> actinique (coup de soleil) malgré une exposition limitée</li>\n                <li>Bulles tendues des mains ou des jambes (« pseudo-porphyrie »)</li>\n                <li>→ <em>Limites nettes s’arrêtant aux zones découvertes</em></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Médicaments inducteurs</strong></td>\n            <td>\n              <ul>\n                <li>Sulfamides, <span class=\"kw-ttt\">AINS</span>, phénothiazines</li>\n                <li>Filtres solaires chimiques, certains végétaux</li>\n              </ul>\n            </td>\n            <td>Cyclines, quinolones, phénothiazines, <span class=\"kw-ttt\">amiodarone</span>, méladinine. <em>(Mnémo « C Q PAM »)</em></td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"115-5","rang":"B","rubrique":"Prévalence/épidémiologie","titre":"Connaître le rôle des infections virales et de l’immunosuppression dans la survenue des toxidermies","contenu":"<p>Plusieurs <strong>facteurs favorisants</strong> sont identifiés pour la survenue d’une toxidermie :</p>\n      <ul>\n        <li><strong>Immunosuppression</strong> (quelle qu’en soit la cause) = facteur favorisant des toxidermies.</li>\n        <li><strong>Facteurs génétiques</strong> : certains groupes HLA.</li>\n        <li><strong>Infections virales</strong> = facteurs favorisants <strong>les mieux documentés</strong> :\n          <ul>\n            <li>Exanthème à l’ampicilline dans la <strong>mononucléose infectieuse</strong></li>\n            <li>Infection par le <strong><span class=\"kw-etio\">VIH</span></strong> → augmente le risque de toxidermies aussi bien bénignes que graves</li>\n            <li>Syndrome d’<span class=\"kw-ci\">hypersensibilité</span> médicamenteuse (<span class=\"kw-alerte\">DRESS</span>) associé à une réactivation de virus du <strong>groupe herpès</strong> (HHV6, HHV7, <span class=\"kw-etio\">EBV</span>, CMV)</li>\n          </ul>\n        </li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>À noter ❌</strong> — l’<strong>atopie</strong> n’est <strong>pas</strong> un <span class=\"kw-def\">facteur de risque</span> de toxidermie.\n      </div>","frequence":0},{"id":"115-6","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir reconnaître une nécrolyse épidermique toxique (Steven-Johnson et Lyell)","contenu":"<div class=\"callout callout-warn\">\n        <strong><span class=\"kw-alerte\">Urgence</span> 🔥.</strong> Les <span class=\"kw-alerte\">NET</span> sont rares mais mettent en jeu le <span class=\"kw-alerte\">pronostic vital</span> → <strong>arrêt immédiat</strong> du médicament suspect + <strong><span class=\"kw-alerte\">hospitalisation</span> en urgence</strong> (médicaments en cause dans <strong><span class=\"kw-chiffre\">70–90 %</span></strong> des cas).\n      </div>\n\n      <p><strong><span class=\"kw-alerte\">SJS</span> / Lyell-NET</strong> = <strong>continuum</strong> :</p>\n      <ul>\n        <li>Mêmes médicaments responsables de tous les grades de sévérité.</li>\n        <li>Seule la <strong>surface d’épiderme nécrosé</strong> (décollé ou décolable) les différencie — c’est le <strong>facteur <span class=\"kw-def\">pronostic</span> majeur ⭐</strong>.</li>\n        <li>Chez de nombreux patients, l’<span class=\"kw-clinique\">éruption</span> s’étend en quelques jours, pouvant passer de SJ à <span class=\"kw-alerte\">Lyell</span>-NET.</li>\n      </ul>\n\n      <table >\n        <thead><tr><th>Item</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Médicaments inducteurs</strong></td>\n            <td>Sulfamides antibactériens, anticomitiaux, <span class=\"kw-ttt\">AINS</span> (oxicams), allopurinol, névirapine.</td>\n          </tr>\n          <tr>\n            <td><strong>Délai d’apparition</strong></td>\n            <td><strong><span class=\"kw-chiffre\">4 à 28 jours</span></strong> après le début du traitement inducteur.</td>\n          </tr>\n          <tr>\n            <td><strong>Phase initiale</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Éruption</span> érythémateuse : <strong>douloureuse</strong> et non prurigineuse</li>\n                <li>Brûlures oculaires, pharyngite</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Phase d’état</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Évolution</span> rapide en quelques <strong>heures-jours</strong>, tableau caractéristique :\n              <ul>\n                <li><span class=\"kw-clinique\">Fièvre</span> + état général très altéré</li>\n                <li>Érosions muqueuses multifocales + bulles cutanées + <strong>signe de Nikolsky</strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <section class=\"lane\">\n        <h4><span class=\"kw-alerte\">Stevens-Johnson</span></h4>\n        <ul>\n          <li>Bulles et vésicules disséminées <strong>restent distinctes</strong> et de petite taille</li>\n          <li>Zones de décollement par confluence <strong>limitées (&lt;<span class=\"kw-chiffre\"> 10 %</span>)</strong> de la surface cutanée</li>\n        </ul>\n      </section>\n\n      <section class=\"lane\">\n        <h4><span class=\"kw-alerte\">Lyell</span>-NET</h4>\n        <ul>\n          <li><strong>Vastes lambeaux d’épiderme</strong> décollés, mettant à nu le <strong>derme suintant rouge-vif</strong></li>\n          <li>Décollement cutané <strong>&gt;<span class=\"kw-chiffre\"> 30 %</span></strong> de la surface corporelle</li>\n        </ul>\n      </section>\n\n      <div class=\"callout callout-warn\">\n        <strong>Atteintes viscérales possibles ⚠️</strong>\n        <ul>\n          <li><span class=\"kw-clinique\">Polypnée</span> + hypoxémie (<span class=\"kw-clinique\">nécrose</span> de l’épithélium bronchique) → <span class=\"kw-def\">pronostic</span> très défavorable</li>\n          <li>Colite (<span class=\"kw-clinique\">nécrose</span> de l’épithélium intestinal)</li>\n        </ul>\n      </div>\n\n      <table >\n        <thead><tr><th>Item</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Paraclinique</strong></td>\n            <td>\n              <ul>\n                <li>Biologie : <strong>leucopénie</strong>, signes de <span class=\"kw-alerte\">défaillance</span> multiviscérale, <strong>troubles hydroélectrolytiques</strong> des déperditions cutanées</li>\n                <li><span class=\"kw-bio\">Biopsie</span> cutanée :\n                  <ul>\n                    <li>Épiderme nécrosé sur <strong>toute son épaisseur</strong>, se détachant d’un derme peu modifié (infiltrat <strong>lymphocytaire</strong> discret)</li>\n                    <li><strong>IFD négative</strong> (<span class=\"kw-def\">diagnostic différentiel</span> avec DBAI)</li>\n                  </ul>\n                </li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Pronostic</span></strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-def\">Mortalité</span> élevée : <strong><span class=\"kw-chiffre\">20–25 %</span></strong> 🏴‍☠️</li>\n                <li>Ré-épidermisation en <strong><span class=\"kw-chiffre\">10–30 jours</span></strong></li>\n                <li>Séquelles fréquentes : troubles pigmentaires + <strong>cicatrices muqueuses</strong> (surtout oculaires = <strong>synéchies</strong>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Diagnostics différentiels ⭐</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">SJS</span> : <span class=\"kw-clinique\">érythème</span> polymorphe majeur / bulleux</li>\n                <li><span class=\"kw-alerte\">Lyell</span>-NET :\n                  <ul>\n                    <li><strong>DBAI</strong> : pas de <span class=\"kw-clinique\">nécrose</span> épidermique, dépôts d’AC en IFD</li>\n                    <li><strong>Brûlures</strong> : absence de lésions muqueuses, <span class=\"kw-clinique\">nécrose</span> cutanée de profondeur variable</li>\n                    <li><strong>Épidermolyse staphylococcique</strong> : nourrisson, pas d’atteinte muqueuse, décollements superficiels (sous-cornés à l’<span class=\"kw-bio\">histologie</span>) péri-orificiels et grands plis</li>\n                  </ul>\n                </li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 112 — Dermatoses bulleuses auto-immunes (DBAI, IFD) · 326 — Bon usage du médicament · 325 — Iatrogénie</em></p>","frequence":3},{"id":"115-7","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir reconnaître une urticaire induite par les médicaments nécessitant l’arrêt du médicament","contenu":"<p>Trois grandes formes d’<span class=\"kw-clinique\">urticaire</span> / angioedème médicamenteuse à connaître :</p>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Urticaire</span> superficielle</strong></li>\n        <li><strong>Angioedème</strong> (<span class=\"kw-clinique\">urticaire</span> profonde)</li>\n        <li><strong>Anaphylaxie</strong> — impose un traitement d’<span class=\"kw-alerte\">urgence</span></li>\n      </ul>\n\n      <table >\n        <thead><tr><th>Item</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Proportion de cause médicamenteuse</strong></td>\n            <td>Seulement <strong>&lt;<span class=\"kw-chiffre\"> 10 %</span></strong> des urticaires aiguës ont une cause médicamenteuse → de nombreuses infections peuvent en être responsables (virales, surtout chez l’enfant).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <section class=\"lane\">\n        <h4>Mécanisme par histaminolibération</h4>\n        <ul>\n          <li><strong><span class=\"kw-ci\">Hypersensibilité</span> immédiate IgE médiée</strong> : témoigne d’une <strong>sensibilisation préalable</strong> (n’apparaît pas lors du 1ᵉʳ contact). <span class=\"kw-alerte\">Contre-indique formellement l’emploi ultérieur du médicament ⚠️</span> (risque d’<span class=\"kw-alerte\">anaphylaxie</span>).</li>\n          <li><strong>Activation pharmacologique non IgE-dépendante</strong> des médiateurs de l’inflammation (<span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">aspirine</span> à dose anti-<span class=\"kw-etio\">inflammatoire</span>, pénicillines, <span class=\"kw-ttt\">codéine</span>…) → réactions <strong>inconstantes</strong>, <strong>dose-dépendantes</strong>, avec <strong>risque de récidive</strong> pour l’ensemble des produits de même effet pharmacologique (même de formule chimique différente).</li>\n        </ul>\n      </section>\n\n      <section class=\"lane\">\n        <h4>Mécanisme par autres neuromédiateurs</h4>\n        <ul>\n          <li><strong>Angioedème aux <span class=\"kw-ttt\">AINS</span></strong> : accumulation de leucotriènes (déviation du métabolisme).</li>\n          <li><strong>Angioedème induit par <span class=\"kw-ttt\">IEC</span> ou <span class=\"kw-ttt\">gliptine</span></strong> : accumulation de <strong>bradykinine</strong>.</li>\n        </ul>\n      </section>\n\n      <div class=\"callout callout-warn\">\n        <strong>CAT.</strong> Devant une <span class=\"kw-clinique\">urticaire</span> / angioedème de mécanisme <span class=\"kw-etio\">allergique</span> IgE médié → <strong>arrêt définitif</strong> + <span class=\"kw-ci\">contre-indication</span> formelle ultérieure du médicament. Documenter sur carnet de santé / document remis au malade.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 187 — <span class=\"kw-ci\">Hypersensibilité</span> et allergies cutanéomuqueuses · 188 — Asthme - Rhinite · 338 — <span class=\"kw-clinique\">Œdème</span> de Quincke et <span class=\"kw-alerte\">anaphylaxie</span></em></p>","frequence":1},{"id":"115-8","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir reconnaître un angioœdème et un choc anaphylactique induit par les médicaments","contenu":"<div class=\"callout callout-warn\">\n        <strong><span class=\"kw-alerte\">Urgence</span> vitale 🔥.</strong> L’<span class=\"kw-alerte\">anaphylaxie</span> médicamenteuse impose un traitement d’urgence + arrêt définitif du médicament responsable.\n      </div>\n\n      <h4>Tableau : caractéristiques épidémiologiques</h4>\n      <table class=\"matrix\">\n        <thead>\n          <tr><th>Aspect clinique</th><th>Part médicamenteuse</th><th>Délai</th><th><span class=\"kw-def\">Mortalité</span></th><th>Médicaments inducteurs</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Urticaire</span></strong> <em>(<span class=\"kw-chiffre\">20–30 %</span>)</em></td>\n            <td>&lt;<span class=\"kw-chiffre\"> 10 %</span></td>\n            <td>Minutes, heures</td>\n            <td>Non</td>\n            <td>Pénicillines, produits de contraste iodés</td>\n          </tr>\n          <tr>\n            <td><strong>Anaphylaxie</strong></td>\n            <td><span class=\"kw-chiffre\">30 %</span></td>\n            <td>Quelques minutes</td>\n            <td><strong><span class=\"kw-chiffre\">5 %</span></strong> 🏴‍☠️</td>\n            <td>Curares, <span class=\"kw-ttt\">AINS</span>, sérums et vaccins</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <section class=\"lane\">\n        <h4>Angioedème — formes à reconnaître</h4>\n        <ul>\n          <li><strong>Histaminique IgE médié</strong> : association possible à une <span class=\"kw-clinique\">urticaire</span>, <span class=\"kw-clinique\">prurit</span>, contexte <span class=\"kw-etio\">allergique</span>. Réponse à l’<span class=\"kw-ttt\">adrénaline</span> + antihistaminiques.</li>\n          <li><strong>Bradykinique</strong> (<span class=\"kw-ttt\">IEC</span>, <span class=\"kw-ttt\">gliptines</span>, <span class=\"kw-ttt\">AINS</span>) : <em>pas</em> d’<span class=\"kw-clinique\">urticaire</span> associée, <em>pas</em> de <span class=\"kw-clinique\">prurit</span>, peu / pas de réponse aux antihistaminiques + <span class=\"kw-ttt\">corticoïdes</span>. Atteinte de la face / VAS possible.</li>\n        </ul>\n      </section>\n\n      <section class=\"lane\">\n        <h4><span class=\"kw-def\">Choc anaphylactique</span></h4>\n        <ul>\n          <li>Tableau d’<strong><span class=\"kw-ci\">hypersensibilité</span> immédiate</strong> systémique : <span class=\"kw-clinique\">urticaire</span>, angioedème, bronchospasme, <span class=\"kw-clinique\">hypotension</span>, <span class=\"kw-alerte\">choc</span>.</li>\n          <li>Délai très court (minutes) après prise médicamenteuse.</li>\n          <li><strong>Adrénaline IM</strong> en <span class=\"kw-alerte\">urgence</span> + arrêt définitif du médicament + déclaration pharmacovigilance.</li>\n        </ul>\n      </section>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 338 — <span class=\"kw-clinique\">Œdème</span> de Quincke et <span class=\"kw-alerte\">anaphylaxie</span> · 187 — <span class=\"kw-ci\">Hypersensibilité</span> et allergies cutanéomuqueuses · 332 — État de <span class=\"kw-alerte\">choc</span></em></p>","frequence":0},{"id":"115-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les différents types de lésions cutanées induites par un médicament","contenu":"<p><strong>Tableau de référence EDN ⭐⭐⭐⭐⭐⭐⭐</strong> — objectif <em>massivement tombé</em> aux QCM. À mémoriser : aspect / part médicamenteuse / délai / <span class=\"kw-def\">mortalité</span> / médicaments / topographie / <span class=\"kw-clinique\">évolution</span>.</p>\n\n      <table class=\"matrix\">\n        <thead>\n          <tr>\n            <th>Aspect clinique</th>\n            <th>Part médicamenteuse</th>\n            <th>Délai</th>\n            <th>Mortalité</th>\n            <th>Médicaments inducteurs</th>\n            <th>Topographie</th>\n            <th>Évolution</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Exanthème maculo-papuleux</strong> <em>(<span class=\"kw-chiffre\">40–60 %</span>)</em></td>\n            <td>Enfant :<span class=\"kw-chiffre\"> 10–20 %</span><br>Adulte :<span class=\"kw-chiffre\"> 50–70 %</span></td>\n            <td><strong>4–14 j</strong> <em>(classique 8–10 j)</em></td>\n            <td>Non</td>\n            <td>Aminopénicillines, β-lactamines, <span class=\"kw-ttt\">sulfamides</span> antibactériens, antituberculeux, antimitotiques</td>\n            <td>Tronc, racines des membres</td>\n            <td><span class=\"kw-chiffre\">7–8 jours</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Urticaire</span></strong> <em>(<span class=\"kw-chiffre\">20–30 %</span>)</em></td>\n            <td>&lt;<span class=\"kw-chiffre\"> 10 %</span></td>\n            <td>Minutes, heures</td>\n            <td>Non</td>\n            <td>Pénicillines, PCI</td>\n            <td>—</td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong>Anaphylaxie</strong></td>\n            <td><span class=\"kw-chiffre\">30 %</span></td>\n            <td>Quelques minutes</td>\n            <td><strong><span class=\"kw-chiffre\">5 %</span></strong></td>\n            <td>Curares, <span class=\"kw-ttt\">AINS</span>, sérums, vaccins</td>\n            <td>—</td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong>Phototoxicité</strong></td>\n            <td>?</td>\n            <td>Heures après <span class=\"kw-etio\">exposition solaire</span></td>\n            <td>&lt;<span class=\"kw-chiffre\"> 1 %</span></td>\n            <td>Cyclines, quinolones, phénothiazines, <span class=\"kw-ttt\">amiodarone</span>, méladinine</td>\n            <td>Zones découvertes</td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong>Photo-<span class=\"kw-ci\">allergie</span></strong></td>\n            <td>?</td>\n            <td><span class=\"kw-chiffre\">7–21 jours</span></td>\n            <td>—</td>\n            <td>Phénothiazines, <span class=\"kw-ttt\">sulfamides</span>, <span class=\"kw-ttt\">AINS</span></td>\n            <td>Zones découvertes (extension possible)</td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Érythème</span> pigmenté fixe</strong></td>\n            <td><strong><span class=\"kw-chiffre\">99 %</span></strong> <em>(pathognomonique)</em></td>\n            <td>Heures à<span class=\"kw-chiffre\"> 2 jours</span></td>\n            <td>Non</td>\n            <td><span class=\"kw-ttt\">Paracétamol</span>, <span class=\"kw-ttt\">AINS</span></td>\n            <td>OGE, lèvres</td>\n            <td>Rapide</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">PEAG</span></strong> <em>(Pustulose Exanthématique Aiguë Généralisée)</em></td>\n            <td><span class=\"kw-chiffre\">70–90 %</span></td>\n            <td><span class=\"kw-chiffre\">1–11 jours</span></td>\n            <td><strong><span class=\"kw-chiffre\">2–5 %</span></strong></td>\n            <td>Aminopénicillines, pristinamycine, quinolones, <span class=\"kw-ttt\">sulfamides</span>, diltiazem, terbinafine, <span class=\"kw-ttt\">hydroxychloroquine</span></td>\n            <td>Grands plis</td>\n            <td>Régression rapide (quelques jours)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">DRESS</span></strong> <em>(Drug <span class=\"kw-clinique\">Rash</span> with Eosinophilia and Systemic Symptoms)</em></td>\n            <td><span class=\"kw-chiffre\">70–90 %</span></td>\n            <td><strong><span class=\"kw-chiffre\">2–6 semaines</span></strong>, mais délai court possible</td>\n            <td><strong><span class=\"kw-chiffre\">5–10 %</span></strong></td>\n            <td>Anticonvulsivants, <span class=\"kw-ttt\">sulfamides</span>, <strong>minocycline, allopurinol</strong>, <span class=\"kw-ttt\">IPP</span>, PCI</td>\n            <td>—</td>\n            <td>Régression lente (quelques semaines)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Stevens-Johnson</span> / Lyell-NET</strong></td>\n            <td><span class=\"kw-chiffre\">70–90 %</span></td>\n            <td><span class=\"kw-chiffre\">4–28 jours</span></td>\n            <td><strong><span class=\"kw-chiffre\">20–25 %</span></strong> 🏴‍☠️</td>\n            <td>Sulfamides antibactériens, anticonvulsivants, <span class=\"kw-ttt\">AINS</span> (oxicams), allopurinol, névirapine</td>\n            <td>—</td>\n            <td>Ré-épidermisation 10–30 j avec séquelles</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Formes non graves — détails à connaître</h4>\n\n      <section class=\"lane\">\n        <h4>Toxidermie érythémateuse (exanthème maculo-papuleux) —<span class=\"kw-chiffre\"> 40–60 %</span> des toxidermies</h4>\n        <table >\n          <tbody>\n            <tr>\n              <td><strong>Délai</strong></td>\n              <td>Début <strong>4–14 j</strong> après le début du traitement (classiquement 8–10 j : « <span class=\"kw-clinique\">érythème</span> du 9ᵉ jour »)</td>\n            </tr>\n            <tr>\n              <td><strong>Médicaments</strong></td>\n              <td>BS 3A : β-lactamines, <span class=\"kw-ttt\">sulfamides</span> antibactériens, aminopénicillines, antituberculeux, anticomitiaux</td>\n            </tr>\n            <tr>\n              <td><strong>Localisations</strong></td>\n              <td>Atteinte initiale au tronc et racines des membres, puis extension possible</td>\n            </tr>\n            <tr>\n              <td><strong><span class=\"kw-clinique\">Éruption</span></strong></td>\n              <td>\n                <ul>\n                  <li>Exanthème <strong>morbilliforme</strong> (maculo-papuleux rouges, confluant en plaques séparées par des espaces de peau saine)</li>\n                  <li>Exanthème <strong>scarlatiniforme</strong> (lésions en nappes confluentes, sans intervalle de peau saine)</li>\n                  <li>Papules / plaques œdémateuses (parfois arciformes)</li>\n                  <li><span class=\"kw-def\">Purpura</span> pétéchial déclive (jambes), souvent si <span class=\"kw-clinique\">érythème</span> intense</li>\n                  <li><strong>Absence habituelle d’énanthème ❌</strong> <em>(à la différence des éruptions virales)</em></li>\n                </ul>\n              </td>\n            </tr>\n            <tr>\n              <td><strong>Signes associés</strong></td>\n              <td><span class=\"kw-clinique\">Prurit</span> fréquent, <span class=\"kw-clinique\">fièvre</span> modérée ou absente</td>\n            </tr>\n            <tr>\n              <td><strong><span class=\"kw-clinique\">Évolution</span></strong></td>\n              <td>Favorable en <strong>7–10 j</strong> après arrêt (fine desquamation en fin d’<span class=\"kw-clinique\">évolution</span>)</td>\n            </tr>\n            <tr>\n              <td><strong>Paraclinique</strong></td>\n              <td>\n                <ul>\n                  <li>Diagnostic clinique</li>\n                  <li>Éosinophilie possible, modérée (&lt; <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> G/L</span>)</li>\n                  <li><strong>Vérifier absence d’atteinte rénale et hépatique ⚠️</strong> (<span class=\"kw-alerte\">signes de gravité</span>)</li>\n                </ul>\n              </td>\n            </tr>\n            <tr>\n              <td><strong>DD</strong></td>\n              <td>Enfant 👦 : <span class=\"kw-etio\">médicamenteux</span> <span class=\"kw-chiffre\">10–20 %</span> (<span class=\"kw-etio\">infectieux</span> <span class=\"kw-chiffre\">70–80 %</span>) · Adulte 👨 : médicamenteux <span class=\"kw-chiffre\">50–70 %</span>. En faveur d’une cause infectieuse 🦠 : contage, énanthème, <span class=\"kw-clinique\">syndrome infectieux</span>, caractère monomorphe.</td>\n            </tr>\n          </tbody>\n        </table>\n      </section>\n\n      <section class=\"lane\">\n        <h4><span class=\"kw-clinique\">Érythème</span> pigmenté fixe</h4>\n        <table >\n          <tbody>\n            <tr><td><strong>Délai</strong></td><td>Début rapide : <strong>&lt;<span class=\"kw-chiffre\"> 48 h</span></strong> après la prise</td></tr>\n            <tr><td><strong>Médicaments</strong></td><td><span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">Paracétamol</span></td></tr>\n            <tr><td><strong>Localisations</strong></td><td>OGE, lèvres (atteinte muqueuse rarement multifocale)</td></tr>\n            <tr>\n              <td><strong>Clinique</strong></td>\n              <td>\n                <ul>\n                  <li>Macules érythémateuses arrondies (1 à 10 macules de quelques centimètres) : souvent <strong>douloureuses</strong> et <strong>infiltrées</strong> → deviennent des plaques</li>\n                  <li><span class=\"kw-clinique\">Évolution</span> bulleuse et généralisée possible ⚠️</li>\n                </ul>\n              </td>\n            </tr>\n            <tr>\n              <td><strong><span class=\"kw-clinique\">Évolution</span></strong></td>\n              <td>\n                <ul>\n                  <li>Disparition des lésions inflammatoires en quelques jours, laissant place à des <strong>taches pigmentées</strong>, brunes ou ardoisées</li>\n                  <li>Si réintroduction ⚠️ : <strong>récidive rapide aux mêmes sites</strong></li>\n                </ul>\n              </td>\n            </tr>\n            <tr><td><strong>DD</strong></td><td><strong>Pathognomonique d’une toxidermie</strong> → seule dermatose de cause quasi-exclusivement médicamenteuse</td></tr>\n          </tbody>\n        </table>\n      </section>\n\n      <section class=\"lane\">\n        <h4><span class=\"kw-alerte\">PEAG</span> (Pustulose Exanthématique Aiguë Généralisée)</h4>\n        <table >\n          <tbody>\n            <tr><td><strong>Délai</strong></td><td><strong>1–11 j</strong> après l’administration du traitement (souvent ATB)</td></tr>\n            <tr><td><strong>Médicaments</strong></td><td>ATB (aminopénicillines, pristinamycine, quinolones, <span class=\"kw-ttt\">sulfamides</span>), diltiazem, terbinafine, <span class=\"kw-ttt\">hydroxychloroquine</span> — <strong><span class=\"kw-chiffre\">70–90 %</span></strong> <span class=\"kw-etio\">médicamenteux</span></td></tr>\n            <tr><td><strong>Localisation</strong></td><td>Prédomine au niveau des <strong>grands plis</strong> (aisselles, aines…)</td></tr>\n            <tr>\n              <td><strong><span class=\"kw-clinique\">Éruption</span></strong></td>\n              <td>\n                <ul>\n                  <li>Brutale et <strong>très fébrile</strong> 🥵 (prise à tort pour une infection)</li>\n                  <li>1/ <span class=\"kw-clinique\">Érythème</span> en nappe, scarlatiniforme</li>\n                  <li>2/ En quelques heures : <strong>nombreuses pustules amicrobiennes superficielles ⭐</strong>, &lt;<span class=\"kw-chiffre\"> 2 mm</span>, contenu lactescent</li>\n                  <li>3/ Confluence possible → détachement partiel de la partie superficielle (sous-cornée)</li>\n                </ul>\n              </td>\n            </tr>\n            <tr><td><strong>Signes associés</strong></td><td><span class=\"kw-clinique\">AEG</span>, <span class=\"kw-clinique\">fièvre</span> élevée, atteinte muqueuse inconstante</td></tr>\n            <tr><td><strong>Paraclinique</strong></td><td><strong>Hyper-PNN ⭐</strong>, <span class=\"kw-bio\">biopsie</span> : accumulation de PNN dans la partie superficielle de l’épiderme (pustules sous-cornées)</td></tr>\n            <tr><td><strong><span class=\"kw-clinique\">Évolution</span></strong></td><td>Régression rapide après l’arrêt → disparition des pustules en quelques jours avec desquamation diffuse. <span class=\"kw-def\">Mortalité</span> <strong><span class=\"kw-chiffre\">2–5 %</span></strong> 🏴‍☠️</td></tr>\n            <tr><td><strong>DD</strong></td><td><span class=\"kw-clinique\">Psoriasis</span> pustuleux généralisé : début moins brutal, <span class=\"kw-clinique\">évolution</span> plus prolongée, ATCD de psoriasis, <span class=\"kw-bio\">histologie</span> souvent non discriminante ❌</td></tr>\n          </tbody>\n        </table>\n      </section>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 114 — Exanthème et érythrodermie · 187 — <span class=\"kw-ci\">Hypersensibilité</span> et allergies cutanéomuqueuses</em></p>","frequence":7},{"id":"115-10","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir imputer un médicament devant une manifestation cutanée","contenu":"<p>Le diagnostic d’imputabilité repose sur un <strong>faisceau d’arguments</strong> qui combine deux composantes : <strong>intrinsèque</strong> (lien chez ce patient) et <strong>extrinsèque</strong> (notoriété dans la littérature).</p>\n\n      <h4>Imputabilité intrinsèque</h4>\n      <p>Évalue chez un patient donné le lien de causalité entre les prises médicamenteuses, la clinique et la chronologie des événements.</p>\n\n      <section class=\"lane\">\n        <h4>Imputabilité chronologique</h4>\n        <ul>\n          <li><strong>Délais évocateurs</strong> dépendants du type de réaction (cf. tableau de référence)</li>\n          <li><strong><span class=\"kw-clinique\">Évolution</span></strong> : amélioration après arrêt, ou aggravation après poursuite du médicament</li>\n          <li><strong>Réintroduction accidentelle</strong> induisant une récidive (on évite la reproduction par réintroduction volontaire)</li>\n        </ul>\n      </section>\n\n      <section class=\"lane\">\n        <h4>Imputabilité sémiologique</h4>\n        <ul>\n          <li>Aspect clinique caractéristique d’un accident <span class=\"kw-etio\">médicamenteux</span></li>\n          <li><strong><span class=\"kw-clinique\">Érythème</span> pigmenté fixe</strong> = <strong>pathognomonique</strong></li>\n          <li>Argument acceptable aussi pour <strong><span class=\"kw-alerte\">DRESS</span>, PEAG, Stevens-Johnson, Lyell-NET</strong> <em>(cause médicamenteuse dans <span class=\"kw-chiffre\">70–90 %</span> des cas)</em></li>\n        </ul>\n      </section>\n\n      <section class=\"lane\">\n        <h4>Facteurs favorisants (cf. obj. dédié)</h4>\n        <ul>\n          <li>Immunosuppression (quelle qu’en soit la cause)</li>\n          <li>Facteurs génétiques (certains groupes HLA)</li>\n          <li>Infections virales : MNI (ampicilline), <span class=\"kw-etio\">VIH</span>, herpès-virus (HHV6, HHV7, EBV, CMV)</li>\n          <li>L’atopie n’est <strong>pas</strong> un FdR ❌</li>\n        </ul>\n      </section>\n\n      <section class=\"lane\">\n        <h4>Tests biologiques</h4>\n        <p>Nombreux tests in vitro / in vivo proposés pour confirmer un diagnostic de toxidermie ; les situations où leur valeur a été validée restent <strong>rares</strong> (prick tests pour les réactions d’<span class=\"kw-ci\">hypersensibilité</span> immédiate à la pénicilline ou aux curarisants).</p>\n      </section>\n\n      <h4>Imputabilité extrinsèque : notoriété</h4>\n      <ul>\n        <li>Source : <strong>littérature</strong> + <strong>banque de pharmacovigilance</strong></li>\n        <li><strong>Certains médicaments sont plus fréquemment inducteurs d’un type de toxidermie</strong> = argument fort, surtout pour les patients prenant plusieurs médicaments</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Au terme de cette démarche</strong>, on détermine le ou les médicament(s) suspect(s). En cas de réaction grave, l’utilisation ultérieure du médicament est <strong><span class=\"kw-ci\">contre-indiquée</span> par écrit</strong> sur un document remis au malade ou sur le carnet de santé.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 326 — Bon usage du médicament · 325 — Iatrogénie · 187 — <span class=\"kw-ci\">Hypersensibilité</span> et allergies cutanéomuqueuses</em></p>","frequence":5},{"id":"115-11","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir reconnaître un DRESS (Drug Reaction with Eosinophilia and Systemic Symptoms)","contenu":"<div class=\"callout callout-warn\">\n        <strong><span class=\"kw-alerte\">Toxidermie grave</span> 🔥.</strong> Médicaments en cause dans <strong><span class=\"kw-chiffre\">70–90 %</span></strong> des cas → arrêt immédiat + <span class=\"kw-alerte\">hospitalisation</span> en <span class=\"kw-alerte\">urgence</span>.\n      </div>\n\n      <table >\n        <thead><tr><th>Item</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Délai</strong></td>\n            <td>Début <strong><span class=\"kw-chiffre\">2 à 8 semaines</span></strong> après l’introduction du traitement (rarement après <span class=\"kw-chiffre\">3 mois</span>, mais possible plus tôt — avant <span class=\"kw-chiffre\">2 semaines</span>).</td>\n          </tr>\n          <tr>\n            <td><strong>Médicaments inducteurs</strong></td>\n            <td>Anticomitiaux, <span class=\"kw-ttt\">sulfamides</span>, <strong>minocycline, allopurinol</strong>, <span class=\"kw-ttt\">IPP</span>, produits de contraste iodés.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td>Sujet <strong>noir</strong> semble avoir un risque accru 🧑🏿‍🦱.</td>\n          </tr>\n          <tr>\n            <td><strong>Clinique</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Éruption</span> évoluant vers une <span class=\"kw-alerte\">érythrodermie</span>, avec <strong><span class=\"kw-ttt\">infiltration</span> de l’<span class=\"kw-clinique\">éruption</span></strong> (<span class=\"kw-clinique\">œdème</span> du visage et des extrémités) <strong>++</strong></li>\n                <li><strong><span class=\"kw-clinique\">Prurit</span> sévère</strong></li>\n                <li><span class=\"kw-clinique\">Fièvre</span> <strong>élevée</strong>, polyadénopathies ⭐</li>\n                <li>Réactivation des virus du groupe herpès 🦠 : <strong>HHV6 ++</strong> et HHV7, <span class=\"kw-etio\">EBV</span>, CMV</li>\n                <li>Atteinte muqueuse possible : cavité buccale et pharynx</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Signes biologiques</strong></td>\n            <td>\n              <ul>\n                <li><strong>Hyperéosinophilie</strong> (&gt; 1500/mm³) : parfois retardée</li>\n                <li>Lymphocytose avec syndrome mononucléosique possible</li>\n                <li>Cytolyse hépatique</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Complications ⚠️</strong>\n        <ul>\n          <li><strong><span class=\"kw-def\">Hépatite</span> fulminante</strong></li>\n          <li><strong><span class=\"kw-def\">Insuffisance rénale aiguë</span></strong> (néphropathie interstitielle immuno-<span class=\"kw-etio\">allergique</span>)</li>\n          <li>Plus rarement : pneumopathie interstitielle, myocardite, syndrome d’activation macrophagique</li>\n        </ul>\n      </div>\n\n      <table >\n        <thead><tr><th>Item</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Paraclinique</strong></td>\n            <td>\n              <ul>\n                <li>Indispensable : <strong><span class=\"kw-bio\">NFS</span></strong> + fonction <strong>rénale</strong> + fonction <strong>hépatique</strong></li>\n                <li><span class=\"kw-bio\">Biopsie</span> : élimine les diagnostics différentiels</li>\n                <li><strong><span class=\"kw-def\">Surveillance</span> <span class=\"kw-bio\">créatininémie</span> + <span class=\"kw-bio\">bilan hépatique</span> impérative (hebdomadaire) ⭐</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Prise en charge</strong></td>\n            <td>\n              <ul>\n                <li>Arrêt du médicament incriminé</li>\n                <li><strong><span class=\"kw-ttt\">Corticothérapie</span> ± immunoglobulines IV</strong></li>\n                <li>Régression lente : en général en plusieurs semaines → attendre avant de juger l’efficacité</li>\n                <li>Plusieurs poussées cutanées/viscérales possibles sur les semaines/mois suivants, avec réactivations virales</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Pronostic</span></strong></td>\n            <td><span class=\"kw-def\">Mortalité</span> <strong><span class=\"kw-chiffre\">5–10 %</span></strong> 🏴‍☠️</td>\n          </tr>\n          <tr>\n            <td><strong>Diagnostics différentiels</strong></td>\n            <td>\n              <ul>\n                <li>Autres érythrodermies : à éliminer par l’interrogatoire, l’<span class=\"kw-bio\">histologie</span>, la numération</li>\n                <li>Syndromes hyperéosinophiliques primitifs/secondaires : début habituellement moins aigu</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 114 — Exanthème et érythrodermie · 326 — Bon usage du médicament · 325 — Iatrogénie</em></p>","frequence":4}],"astuces":[],"strategie":{"urgence":"<p><strong>Principe :</strong> <span class=\"kw-def\">tout médicament</span> peut induire une toxidermie — <span class=\"kw-ci\">ne jamais</span> s'arrêter au « coupable idéal ».<br><strong>Règle de base :</strong> <span class=\"kw-ttt\">arrêt du médicament suspect</span> dès la suspicion.<br><strong>Bénignité habituelle :</strong> <span class=\"kw-chiffre\">> 90 %</span> des toxidermies sont <span class=\"kw-clinique\">bénignes</span>.<br><strong>Urgences vitales :</strong> <span class=\"kw-alerte\">nécrolyse épidermique toxique (Stevens-Johnson / Lyell)</span>, <span class=\"kw-alerte\">DRESS</span>, <span class=\"kw-alerte\">choc anaphylactique</span> → <span class=\"kw-ttt\">arrêt immédiat</span> + <span class=\"kw-alerte\">hospitalisation en urgence</span>.<br><strong>Cinétique :</strong> immédiate en <span class=\"kw-chiffre\">minutes-heures</span> (<span class=\"kw-clinique\">urticaire</span>, <span class=\"kw-alerte\">anaphylaxie</span>) ; retardée en <span class=\"kw-chiffre\">plusieurs jours à semaines</span> (exanthème, <span class=\"kw-alerte\">DRESS</span> <span class=\"kw-chiffre\">2-6 semaines</span>, nécrolyse <span class=\"kw-chiffre\">4-28 jours</span>).</p>","hospit":"<p><strong>Ambulatoire :</strong> toxidermie <span class=\"kw-clinique\">bénigne</span> (exanthème maculo-papuleux, <span class=\"kw-clinique\">urticaire</span>, <span class=\"kw-clinique\">érythème</span> pigmenté fixe) → <span class=\"kw-ttt\">arrêt du médicament</span> et <span class=\"kw-def\">surveillance</span>.<br><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> dès l'apparition d'un <span class=\"kw-alerte\">signe de gravité</span>.<br><strong><span class=\"kw-alerte\">Urgence</span> :</strong> <span class=\"kw-etio\">nécrolyse épidermique toxique</span>, <span class=\"kw-etio\">DRESS</span>, <span class=\"kw-etio\">PEAG</span> → <span class=\"kw-alerte\">hospitalisation en urgence</span> + <span class=\"kw-ttt\">arrêt immédiat du médicament suspect</span>.<br><strong>Anaphylaxie / <span class=\"kw-alerte\">choc</span> :</strong> <span class=\"kw-alerte\">traitement d'urgence</span> immédiat.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Exanthème généralisé</span> ou <span class=\"kw-alerte\">extension très rapide</span> de l'<span class=\"kw-clinique\">éruption</span></li><li><span class=\"kw-clinique\">Infiltration des lésions</span>, en particulier <span class=\"kw-alerte\">œdème du visage</span></li><li><span class=\"kw-clinique\">Fièvre élevée</span>, <span class=\"kw-clinique\">polyadénopathies</span>, <span class=\"kw-alerte\">mauvaise tolérance hémodynamique</span></li><li>Présence de <span class=\"kw-alerte\">vésico-bulles</span> ou de <span class=\"kw-alerte\">pustules</span></li><li><span class=\"kw-alerte\">Éruptions / érosions muqueuses</span></li><li><span class=\"kw-alerte\">Signe de Nikolsky</span> (<span class=\"kw-clinique\">décollement cutané provoqué par un frottement appuyé sur peau saine</span>)</li><li><span class=\"kw-bio\">Atteinte rénale ou hépatique</span> sur le bilan <span class=\"kw-ttt\">biologique</span></li><li><span class=\"kw-clinique\">Douleurs cutanées ou muqueuses</span>, <span class=\"kw-alerte\">purpura infiltré ou nécrose</span>, <span class=\"kw-alerte\">aspect grisâtre de la peau</span> (<span class=\"kw-clinique\">nécrose</span> épidermique)</li></ul>","principes":"<p><span class=\"kw-ttt\">Arrêt du médicament suspect</span> = base du traitement ; les modalités complémentaires dépendent du type de toxidermie.</p><p><strong>Dans tous les cas</strong></p><ul><li><span class=\"kw-ttt\">Arrêt du médicament suspect</span> dès la suspicion (tout médicament peut être en cause)</li><li><span class=\"kw-ttt\">Notification obligatoire</span> aux instances de pharmacovigilance</li><li>Réaction grave → <span class=\"kw-ci\">contre-indication ultérieure écrite</span> (document remis au malade ou carnet de santé)</li></ul><p><strong><span class=\"kw-clinique\">Urticaire</span> / <span class=\"kw-alerte\">anaphylaxie</span> (<span class=\"kw-ci\">hypersensibilité</span> immédiate)</strong></p><p>Survenue en minutes-heures, témoigne d'une sensibilisation préalable</p><ul><li><span class=\"kw-clinique\">Anaphylaxie / choc</span> → <span class=\"kw-alerte\">traitement d'urgence</span> immédiat</li><li>Mécanisme <span class=\"kw-bio\">IgE médié</span> → <span class=\"kw-ci\">contre-indication formelle</span> de l'emploi ultérieur (risque d'<span class=\"kw-alerte\">anaphylaxie</span>)</li></ul><p><strong><span class=\"kw-alerte\">DRESS</span></strong></p><p><span class=\"kw-def\">Surveillance</span> hebdomadaire de la <span class=\"kw-bio\">créatininémie</span> et du <span class=\"kw-bio\">bilan hépatique</span></p><ul><li><span class=\"kw-ttt\">Arrêt du médicament</span> + <span class=\"kw-ttt\">corticothérapie</span> ± <span class=\"kw-ttt\">immunoglobulines IV</span></li><li>Régression lente sur <span class=\"kw-chiffre\">plusieurs semaines</span> ; <span class=\"kw-etio\">poussées cutanées/viscérales</span> possibles</li></ul><p><strong><span class=\"kw-alerte\">PEAG</span> (pustulose exanthématique aiguë généralisée)</strong></p><ul><li><span class=\"kw-ttt\">Arrêt du médicament</span> → régression rapide en <span class=\"kw-chiffre\">quelques jours</span></li></ul><p><strong>Nécrolyse épidermique <span class=\"kw-etio\">toxique</span> (<span class=\"kw-alerte\">Stevens-Johnson</span> / Lyell)</strong></p><p><span class=\"kw-def\">Mortalité</span><span class=\"kw-chiffre\"> 20-25 %</span> — facteur pronostique = surface d'épiderme décollé</p><ul><li><span class=\"kw-alerte\">Hospitalisation en urgence</span> + <span class=\"kw-ttt\">arrêt immédiat</span> du médicament</li><li>Correction des <span class=\"kw-bio\">troubles hydro-électrolytiques</span> liés aux déperditions cutanées</li></ul>","suivi":"<p><strong>Exanthème :</strong> <span class=\"kw-clinique\">évolution</span> favorable en <span class=\"kw-chiffre\">7-10 jours</span> après l'arrêt ; vérifier l'<span class=\"kw-bio\">absence d'atteinte rénale et hépatique</span>.<br><strong><span class=\"kw-alerte\">DRESS</span> :</strong> <span class=\"kw-def\">surveillance</span> <span class=\"kw-chiffre\">hebdomadaire</span> de la <span class=\"kw-bio\">créatininémie</span> et du <span class=\"kw-bio\">bilan hépatique</span> ; <span class=\"kw-etio\">poussées</span> possibles sur plusieurs semaines/mois.<br><strong>Nécrolyse épidermique <span class=\"kw-etio\">toxique</span> :</strong> ré-épidermisation en <span class=\"kw-chiffre\">10-30 jours</span>, <span class=\"kw-etio\">séquelles</span> fréquentes (troubles pigmentaires, <span class=\"kw-etio\">synéchies oculaires</span>).<br><strong>Toujours :</strong> <span class=\"kw-ttt\">contre-indication écrite</span> remise au patient et <span class=\"kw-ttt\">notification à la pharmacovigilance</span>.</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Éruption cutanée sous médicament — Suspicion de toxidermie — arrêt du médicament suspect","detail":"<h4>CAT — Toxidermie médicamenteuse — Orientation devant une <span class=\"kw-clinique\">éruption</span> cutanée sous médicament</h4>","branches":[{"to":"q-anaph","label":"Évaluation initiale","color":"blue"}]},{"id":"q-anaph","kind":"decision","label":"Angiœdème, choc anaphylactique ou détresse (réaction immédiate) ? — Hypersensibilité immédiate, survenue en minutes-heures","branches":[{"to":"t-anaph","label":"Oui","color":"red"},{"to":"q-grav","label":"Non","color":"blue"}]},{"id":"t-anaph","kind":"terminal","label":"Anaphylaxie / angiœdème — urgence vitale — Traitement d'urgence immédiat","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Traitement d'urgence</span> immédiat</li><li><span class=\"kw-ttt\">Arrêt du médicament</span> en cause</li></ul><h4>Suite</h4><ul><li>Si <span class=\"kw-bio\">IgE médié</span> : <span class=\"kw-ci\">contre-indication formelle</span> de toute réintroduction (risque de récidive)</li></ul>"},{"id":"q-grav","kind":"decision","label":"Signes de gravité présents ? — Œdème du visage, fièvre élevée, vésico-bulles/pustules, érosions muqueuses, signe de Nikolsky, atteinte rénale/hépatique","branches":[{"to":"q-type-grave","label":"Oui — signes de gravité","color":"red"},{"to":"q-type-benin","label":"Non","color":"green"}]},{"id":"q-type-grave","kind":"decision","label":"Quelle présentation de toxidermie grave ? — Orientation selon le tableau dominant","branches":[{"to":"t-net","label":"Bulles, Nikolsky, érosions muqueuses","color":"red"},{"to":"t-dress","label":"Œdème visage + éosinophilie + fièvre (2-6 sem)","color":"red"},{"to":"t-peag","label":"Pustules + fièvre élevée (1-11 j)","color":"amber"}]},{"id":"t-net","kind":"terminal","label":"Nécrolyse épidermique toxique (Stevens-Johnson / Lyell) — Bulles, érosions muqueuses, signe de Nikolsky","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Décollement épidermique</span> : <span class=\"kw-chiffre\">< 10 %</span> (Stevens-Johnson) à <span class=\"kw-chiffre\">> 30 %</span> (Lyell)</li><li><span class=\"kw-clinique\">Érosions muqueuses multifocales</span> + <span class=\"kw-alerte\">signe de Nikolsky</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Arrêt immédiat</span> du médicament + <span class=\"kw-alerte\">hospitalisation en urgence</span></li><li>Correction des <span class=\"kw-bio\">troubles hydro-électrolytiques</span> (déperditions cutanées)</li></ul><h4>Délai</h4><ul><li>Début <span class=\"kw-chiffre\">4 à 28 jours</span> après l'introduction</li></ul><h4>Surveillance</h4><ul><li>Mortalité <span class=\"kw-chiffre\">20-25 %</span> ; ré-épidermisation en <span class=\"kw-chiffre\">10-30 jours</span> avec <span class=\"kw-etio\">séquelles oculaires</span></li></ul>"},{"id":"t-dress","kind":"terminal","label":"DRESS — Œdème du visage, fièvre, adénopathies, éosinophilie","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Éruption infiltrée</span> avec <span class=\"kw-clinique\">œdème du visage</span>, <span class=\"kw-clinique\">fièvre élevée</span>, <span class=\"kw-clinique\">polyadénopathies</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Hyperéosinophilie</span> (<span class=\"kw-chiffre\">> 1500/mm³</span>), <span class=\"kw-bio\">cytolyse hépatique</span> ; <span class=\"kw-etio\">réactivation virale (HHV6)</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Arrêt du médicament</span> + <span class=\"kw-ttt\">corticothérapie</span> ± <span class=\"kw-ttt\">immunoglobulines IV</span></li></ul><h4>Délai</h4><ul><li>Début <span class=\"kw-chiffre\">2 à 6 semaines</span> ; <span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">5-10 %</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-bio\">Créatininémie</span> + <span class=\"kw-bio\">bilan hépatique</span> <span class=\"kw-chiffre\">hebdomadaires</span></li></ul>"},{"id":"t-peag","kind":"terminal","label":"PEAG (pustulose exanthématique aiguë généralisée) — Pustules amicrobiennes + fièvre élevée","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Érythème en nappe</span> des <span class=\"kw-clinique\">grands plis</span> recouvert de <span class=\"kw-clinique\">pustules amicrobiennes</span> (<span class=\"kw-chiffre\">< 2 mm</span>), <span class=\"kw-clinique\">très fébrile</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Hyperleucocytose à PNN</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Arrêt du médicament</span> + <span class=\"kw-alerte\">hospitalisation</span> → régression en quelques jours</li></ul><h4>Délai</h4><ul><li>Début <span class=\"kw-chiffre\">1 à 11 jours</span> ; mortalité <span class=\"kw-chiffre\">2-5 %</span></li></ul>"},{"id":"q-type-benin","kind":"decision","label":"Type de toxidermie bénigne ? — Selon morphologie et délai","branches":[{"to":"t-exanth","label":"Exanthème maculo-papuleux","color":"green"},{"to":"t-urticaire","label":"Urticaire / angiœdème","color":"amber"},{"to":"t-epf","label":"Macules pigmentées récidivantes","color":"green"}]},{"id":"t-exanth","kind":"terminal","label":"Exanthème maculo-papuleux — ambulatoire — 40-60 % des toxidermies","color":"green","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Exanthème morbilliforme/scarlatiniforme</span> du <span class=\"kw-clinique\">tronc</span> et des racines des membres, <span class=\"kw-clinique\">prurit</span>, <span class=\"kw-clinique\">absence d'énanthème</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Arrêt du médicament</span>, prise en charge ambulatoire</li></ul><h4>Paraclinique</h4><ul><li>Vérifier l'<span class=\"kw-bio\">absence d'atteinte rénale et hépatique</span></li></ul><h4>Délai</h4><ul><li>Début <span class=\"kw-chiffre\">4-14 jours</span> ; régression en <span class=\"kw-chiffre\">7-10 jours</span> après l'arrêt</li></ul>"},{"id":"t-urticaire","kind":"terminal","label":"Urticaire / angiœdème — Hypersensibilité immédiate","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Urticaire</span> superficielle ± <span class=\"kw-clinique\">angiœdème</span> ; survenue en <span class=\"kw-chiffre\">minutes-heures</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Arrêt du médicament</span></li></ul><h4>Suite</h4><ul><li>Si mécanisme <span class=\"kw-bio\">IgE médié</span> : <span class=\"kw-ci\">contre-indication formelle</span> de l'emploi ultérieur (risque d'<span class=\"kw-alerte\">anaphylaxie</span>)</li></ul>"},{"id":"t-epf","kind":"terminal","label":"Érythème pigmenté fixe — Pathognomonique d'une toxidermie","color":"green","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Macules arrondies douloureuses et infiltrées</span> (OGE, lèvres), laissant des <span class=\"kw-clinique\">taches pigmentées</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Arrêt du médicament</span> ; <span class=\"kw-ci\">éviter la réintroduction</span> (récidive rapide aux mêmes sites)</li></ul><h4>Délai</h4><ul><li>Début <span class=\"kw-chiffre\">< 48 h</span> après la prise</li></ul>"}]},"cards":[{"i":"1f4d108aed9d","n":115,"o":"115-1","u":"Définition","t":"Connaître la définition d’une toxidermie","q":"Tous les médicaments peuvent-ils être responsables d'une toxidermie ?","a":"<p>Oui, <strong>tout médicament</strong> est susceptible d'induire une toxidermie, même si certaines molécules sont plus fréquemment impliquées que d'autres.</p>"},{"i":"86516168b043","n":115,"o":"115-1","u":"Définition","t":"Connaître la définition d’une toxidermie","q":"Quelle est la définition d'une toxidermie en médecine ?","a":"<p>Une toxidermie désigne l'ensemble des <strong>effets cutanés secondaires</strong> induits par la prise de <strong>médicaments</strong>.</p>"},{"i":"f330c20f8b2e","n":115,"o":"115-1","u":"Définition","t":"Connaître la définition d’une toxidermie","q":"Quelle est l'obligation légale concernant les toxidermies en France ?","a":"<p>Les toxidermies, en tant qu'effets indésirables médicamenteux, sont soumises à une <strong>notification obligatoire</strong> aux instances de <strong>pharmacovigilance</strong>.</p>"},{"i":"4fa184ecb244","n":115,"o":"115-10","u":"Diagnostic positif","t":"Savoir imputer un médicament devant une manifestation cutanée","q":"Qu'est-ce que l'imputabilité extrinsèque dans le diagnostic d'une toxidermie et quelle est son utilité ?","a":"<p>L'imputabilité extrinsèque fait référence à la <strong>notoriété</strong> d'un médicament comme inducteur d'un type de toxidermie, établie à partir de la <strong>littérature médicale</strong> et des <strong>banques de pharmacovigilance</strong>. C'est un argument fort, surtout chez les patients polymédiqués, car certains médicaments sont plus fréquemment associés à des toxidermies spécifiques.</p>"},{"i":"67bd157b0382","n":115,"o":"115-10","u":"Diagnostic positif","t":"Savoir imputer un médicament devant une manifestation cutanée","q":"Sur quels arguments repose le diagnostic d'imputabilité d'un médicament dans une toxidermie ?","a":"<p>Le diagnostic d'imputabilité d'un médicament face à une toxidermie repose sur un <strong>faisceau d'arguments</strong> combinant deux composantes :</p><ul><li>Une composante <strong>intrinsèque</strong>, évaluant le lien de causalité chez le patient.</li><li>Une composante <strong>extrinsèque</strong>, concernant la notoriété du médicament dans la littérature.</li></ul>"},{"i":"9d32866b6099","n":115,"o":"115-10","u":"Diagnostic positif","t":"Savoir imputer un médicament devant une manifestation cutanée","q":"Quels sont les éléments clés de l'imputabilité intrinsèque dans le diagnostic d'une toxidermie ?","a":"<p>L'imputabilité intrinsèque chez un patient donné s'évalue selon :</p><ul><li>L'<strong>imputabilité chronologique</strong> : délais évocateurs (dépendants du type de réaction), amélioration après arrêt du médicament ou aggravation après poursuite, et récidive après réintroduction accidentelle.</li><li>L'<strong>imputabilité sémiologique</strong> : aspect clinique caractéristique (ex: érythème pigmenté fixe est pathognomonique, argument fort pour DRESS, PEAG, SJS, Lyell-NET).</li><li>Les <strong>facteurs favorisants</strong> : immunosuppression, facteurs génétiques (certains groupes HLA), ou certaines infections virales (MNI avec ampicilline, VIH, herpès-virus).</li></ul>"},{"i":"cb7316227db7","n":115,"o":"115-10","u":"Diagnostic positif","t":"Savoir imputer un médicament devant une manifestation cutanée","q":"Quels sont les tests parancliniques utiles pour confirmer le diagnostic de toxidermie et l'imputabilité du médicament ?","a":"<p>Les situations où les tests paracliniques (<em>in vitro</em> ou <em>in vivo</em>) ont une valeur validée pour confirmer le diagnostic de toxidermie sont rares. Cependant, les <strong>prick tests</strong> sont utiles pour les réactions d'hypersensibilité immédiate à la <strong>pénicilline</strong> ou aux <strong>curarisants</strong>.</p>"},{"i":"7ca0504d2b43","n":115,"o":"115-11","u":"Diagnostic positif","t":"Savoir reconnaître un DRESS (Drug Reaction with Eosinophilia and Systemic Symptoms)","q":"Quels sont les signes biologiques clés orientant vers un diagnostic de DRESS (Drug Reaction with Eosinophilia and Systemic Symptoms) ?","a":"<p>Les signes biologiques clés du DRESS incluent :</p><ul><li>Une <strong>hyperéosinophilie</strong> (> 1500/mm³), parfois retardée.</li><li>Une <strong>lymphocytose</strong> avec un syndrome mononucléosique possible.</li><li>Une <strong>cytolyse hépatique</strong>.</li><li>La <strong>réactivation de virus du groupe herpès</strong>, notamment HHV6, HHV7, EBV et CMV.</li></ul>"},{"i":"a25685867791","n":115,"o":"115-11","u":"Diagnostic positif","t":"Savoir reconnaître un DRESS (Drug Reaction with Eosinophilia and Systemic Symptoms)","q":"Quelles sont les principales complications possibles d'un DRESS (Drug Reaction with Eosinophilia and Systemic Symptoms) ?","a":"<p>Les principales complications d'un DRESS sont :</p><ul><li>L'<strong>hépatite fulminante</strong>.</li><li>L'<strong>insuffisance rénale aiguë</strong> (néphropathie interstitielle immuno-allergique).</li><li>Plus rarement, des pneumopathies interstitielles, des myocardites et un syndrome d'activation macrophagique.</li></ul>"},{"i":"bba3876c3400","n":115,"o":"115-11","u":"Diagnostic positif","t":"Savoir reconnaître un DRESS (Drug Reaction with Eosinophilia and Systemic Symptoms)","q":"Quel est le délai d'apparition typique d'un DRESS (Drug Reaction with Eosinophilia and Systemic Symptoms) après l'introduction du médicament en cause ?","a":"<p>Le délai d'apparition typique d'un DRESS est de <strong>2 à 8 semaines</strong> après l'introduction du traitement. Plus rarement, il peut apparaître avant 2 semaines ou après 3 mois.</p>"},{"i":"d4d36e3e2dbb","n":115,"o":"115-11","u":"Diagnostic positif","t":"Savoir reconnaître un DRESS (Drug Reaction with Eosinophilia and Systemic Symptoms)","q":"Quels sont les principaux médicaments inducteurs reconnus du DRESS (Drug Reaction with Eosinophilia and Systemic Symptoms) ?","a":"<p>Les principaux médicaments inducteurs du DRESS sont les <strong>anticomitiaux</strong>, les <strong>sulfamides</strong>, la <strong>minocycline</strong>, l'<strong>allopurinol</strong>, les <strong>IPP</strong> (inhibiteurs de la pompe à protons) et les <strong>produits de contraste iodés</strong>.</p>"},{"i":"fb31d7be5b3b","n":115,"o":"115-11","u":"Diagnostic positif","t":"Savoir reconnaître un DRESS (Drug Reaction with Eosinophilia and Systemic Symptoms)","q":"Comment définir cliniquement un DRESS (Drug Reaction with Eosinophilia and Systemic Symptoms) ?","a":"<p>Le DRESS est une toxidermie grave caractérisée par un tableau clinique associant :</p><ul><li>Une <strong>éruption cutanée</strong> évoluant vers une <strong>érythrodermie</strong>, avec infiltration (<strong>œdème du visage et des extrémités</strong>).</li><li>Un <strong>prurit sévère</strong>.</li><li>Une <strong>fièvre élevée</strong>.</li><li>Des <strong>polyadénopathies</strong>.</li><li>Une <strong>atteinte muqueuse</strong> possible (cavité buccale, pharynx).</li></ul>"},{"i":"0f00b4cda238","n":115,"o":"115-6","u":"Identifier une urgence","t":"Savoir reconnaître une nécrolyse épidermique toxique (Steven-Johnson et Lyell)","q":"Quels sont les principaux médicaments inducteurs des nécrolyses épidermiques toxiques (Steven-Johnson et Lyell) et leur délai d'apparition typique ?","a":"<p>Les principaux médicaments inducteurs sont :</p><ul><li>Les <strong>sulfamides antibactériens</strong></li><li>Les <strong>anticomitiaux</strong></li><li>Certains <strong>AINS</strong> (notamment les oxicams)</li><li>L'<strong>allopurinol</strong></li><li>La <strong>névirapine</strong></li></ul><p>Le délai d'apparition est généralement de <strong>4 à 28 jours</strong> après le début du traitement inducteur.</p>"},{"i":"1745125a5165","n":115,"o":"115-6","u":"Identifier une urgence","t":"Savoir reconnaître une nécrolyse épidermique toxique (Steven-Johnson et Lyell)","q":"Quelles sont les principales atteintes viscérales et complications des nécrolyses épidermiques toxiques (Steven-Johnson et Lyell) ?","a":"<p>Les atteintes viscérales et complications peuvent inclure :</p><ul><li><strong>Atteintes bronchiques</strong> : polypnée et hypoxémie secondaires à la nécrose de l'épithélium bronchique, avec un pronostic très défavorable.</li><li><strong>Atteintes intestinales</strong> : colite due à la nécrose de l'épithélium intestinal.</li><li><strong>Séquelles fréquentes</strong> : troubles pigmentaires et cicatrices muqueuses, notamment <strong>oculaires (synéchies)</strong> pouvant entraîner une cécité.</li><li>Une <strong>mortalité élevée</strong> (environ 20-25%).</li></ul>"},{"i":"67f1b0746ed5","n":115,"o":"115-6","u":"Identifier une urgence","t":"Savoir reconnaître une nécrolyse épidermique toxique (Steven-Johnson et Lyell)","q":"Quel est l'intérêt de la biopsie cutanée et de l'immunofluorescence directe (IFD) dans le diagnostic des nécrolyses épidermiques toxiques (Steven-Johnson et Lyell) ?","a":"<p>La <strong>biopsie cutanée</strong> est essentielle et retrouve une <strong>nécrose épidermique sur toute son épaisseur</strong>, se détachant d'un derme peu modifié avec un infiltrat lymphocytaire discret. Cette image est pathognomonique.</p><p>L'<strong>immunofluorescence directe (IFD) est négative</strong>. Elle permet d'éliminer les diagnostics différentiels comme les dermatoses bulleuses auto-immunes (DBAI), qui présenteraient des dépôts d'anticorps.</p>"},{"i":"d609f4fefde8","n":115,"o":"115-6","u":"Identifier une urgence","t":"Savoir reconnaître une nécrolyse épidermique toxique (Steven-Johnson et Lyell)","q":"Quelle est la présentation clinique initiale et les signes cardinaux de la phase d'état d'une nécrolyse épidermique toxique (Steven-Johnson et Lyell) ?","a":"<p>La phase initiale est caractérisée par :</p><ul><li>Une éruption érythémateuse <strong>douloureuse</strong> et non prurigineuse.</li><li>Des <strong>brûlures oculaires</strong> et une pharyngite.</li></ul><p>La phase d'état, d'évolution rapide, est marquée par :</p><ul><li>Une <strong>fièvre élevée</strong> et un état général très altéré.</li><li>Des <strong>érosions muqueuses multifocales</strong> (orales, oculaires, génitales).</li><li>Des <strong>bulles cutanées</strong>.</li><li>Un <strong>signe de Nikolsky positif</strong> (le frottement de la peau entraîne un décollement épidermique).</li></ul>"},{"i":"f96f7a02d5fa","n":115,"o":"115-6","u":"Identifier une urgence","t":"Savoir reconnaître une nécrolyse épidermique toxique (Steven-Johnson et Lyell)","q":"Comment définit-on et différencie-t-on d'un point de vue clinique le syndrome de Stevens-Johnson (SJS) et la nécrolyse épidermique toxique (NET ou Lyell) ?","a":"<p>Le <strong>SJS</strong> et la <strong>NET</strong> sont un continuum de la même maladie. Ils se distinguent uniquement par l'étendue des zones de décollement cutané :</p><ul><li><strong>Syndrome de Stevens-Johnson (SJS)</strong> : décollement épidermique inférieur à <strong>10%</strong> de la surface corporelle. Les bulles et vésicules sont disséminées mais restent distinctes et de petite taille.</li><li><strong>Nécrolyse Épidermique Toxique (NET ou Lyell)</strong> : décollement épidermique supérieur à <strong>30%</strong> de la surface corporelle. On observe de vastes lambeaux d'épiderme décollés, mettant à nu un derme suintant rouge-vif.</li><li>Une forme intermédiaire existe entre 10% et 30% de décollement.</li></ul><p>Le pourcentage de surface corporelle décollée est le facteur pronostic majeur.</p>"},{"i":"80179771499e","n":115,"o":"115-7","u":"Diagnostic positif","t":"Savoir reconnaître une urticaire induite par les médicaments nécessitant l’arrêt du médicament","q":"Quelle est la conduite à tenir immédiate et à long terme face à une urticaire ou un angioedème médicamenteux de mécanisme IgE-médié ?","a":"<p>Devant une urticaire/angioedème de mécanisme <strong>allergique IgE-médié</strong>, la conduite à tenir est l'<strong>arrêt définitif</strong> et la <strong>contre-indication formelle ultérieure</strong> du médicament incriminé. Il est impératif de <strong>documenter</strong> cette information (carnet de santé, document remis au patient).</p>"},{"i":"ab7e12f7fd41","n":115,"o":"115-7","u":"Diagnostic positif","t":"Savoir reconnaître une urticaire induite par les médicaments nécessitant l’arrêt du médicament","q":"Quelles sont les particularités cliniques et le risque de récidive en cas d'urticaire/anaphylaxie médicamenteuse par activation pharmacologique non IgE-dépendante ?","a":"<p>Dans le cas d'une activation pharmacologique non IgE-dépendante (ex: <strong>AINS</strong>, <strong>aspirine</strong> à dose anti-inflammatoire, <strong>pénicillines</strong>, <strong>codéine</strong>), les réactions sont <strong>inconstantes</strong> et <strong>dose-dépendantes</strong>. Il existe un risque de récidive pour l'ensemble des produits ayant un <strong>même effet pharmacologique</strong>, même si leur formule chimique est différente.</p>"},{"i":"bd9a5a6372b4","n":115,"o":"115-7","u":"Diagnostic positif","t":"Savoir reconnaître une urticaire induite par les médicaments nécessitant l’arrêt du médicament","q":"Quelle proportion des urticaires aiguës a une cause médicamenteuse et quelles autres étiologies sont fréquentes, notamment chez l'enfant ?","a":"<p>Seulement <strong>moins de 10 %</strong> des urticaires aiguës sont d'origine médicamenteuse. De nombreuses <strong>infections</strong>, notamment virales, peuvent en être responsables, surtout chez l'enfant.</p>"},{"i":"e2ef5a51d84d","n":115,"o":"115-7","u":"Diagnostic positif","t":"Savoir reconnaître une urticaire induite par les médicaments nécessitant l’arrêt du médicament","q":"Quels sont les trois principaux mécanismes physiopathologiques des urticaires/angioedèmes médicamenteux à connaître ?","a":"<ul><li><strong>Histaminolibération</strong> par mécanisme IgE-médié (hypersensibilité immédiate).</li><li><strong>Activation pharmacologique non IgE-dépendante</strong> des médiateurs de l'inflammation.</li><li>Mécanismes impliquant d'<strong>autres neuromédiateurs</strong> (ex: accumulation de leucotriènes avec les AINS, ou de bradykinine avec les IEC/gliptines).</li></ul>"},{"i":"12afd3d6e3f5","n":115,"o":"115-8","u":"Identifier une urgence","t":"Savoir reconnaître un angioœdème et un choc anaphylactique induit par les médicaments","q":"Quels sont les signes cliniques clés d'un choc anaphylactique médicamenteux ?","a":"<p>Le tableau clinique d'un choc anaphylactique est une hypersensibilité immédiate systémique caractérisée par l'association d'une <strong>urticaire, un angioœdème, un bronchospasme, une hypotension et un état de choc</strong>. Il survient dans un <strong>délai très court (quelques minutes)</strong> après la prise médicamenteuse.</p>"},{"i":"5d17b6164340","n":115,"o":"115-8","u":"Identifier une urgence","t":"Savoir reconnaître un angioœdème et un choc anaphylactique induit par les médicaments","q":"Comment identifier un angioœdème de type bradykinique induit par les médicaments ?","a":"<p>L'angioœdème bradykinique est souvent induit par les <strong>IEC, les gliptines ou les AINS</strong>. Il se caractérise par l'<strong>absence d'urticaire et de prurit</strong>, et une <strong>faible ou pas de réponse aux antihistaminiques et corticoïdes</strong>. Il peut entraîner une <strong>atteinte de la face et des voies aériennes supérieures (VAS)</strong>.</p>"},{"i":"d026821b2115","n":115,"o":"115-8","u":"Identifier une urgence","t":"Savoir reconnaître un angioœdème et un choc anaphylactique induit par les médicaments","q":"Quelle est la prise en charge immédiate d'un choc anaphylactique médicamenteux ?","a":"<p>La prise en charge immédiate d'un choc anaphylactique médicamenteux repose sur l'administration d'<strong>adrénaline par voie intramusculaire</strong> en urgence, l'<strong>arrêt définitif du médicament</strong> responsable et une <strong>déclaration à la pharmacovigilance</strong>.</p>"},{"i":"e4ed16080979","n":115,"o":"115-8","u":"Identifier une urgence","t":"Savoir reconnaître un angioœdème et un choc anaphylactique induit par les médicaments","q":"Comment identifier un angioœdème de type histaminique induit par les médicaments ?","a":"<p>L'angioœdème histaminique est classiquement <strong>IgE médié</strong> et peut s'associer à une <strong>urticaire</strong> et un <strong>prurit</strong>. Il survient dans un <strong>contexte allergique</strong> et répond généralement bien à l'<strong>adrénaline et aux antihistaminiques</strong>.</p>"},{"i":"269fd5f56d87","n":115,"o":"115-9","u":"Diagnostic positif","t":"Connaître les différents types de lésions cutanées induites par un médicament","q":"Quelles sont les manifestations cliniques et les spécificités du DRESS (Drug Rash with Eosinophilia and Systemic Symptoms) ?","a":"<p>Le DRESS est une toxidermie grave qui se manifeste entre <strong>2 à 6 semaines</strong> après l'introduction du médicament, bien qu'un délai plus court soit possible. Il associe une éruption cutanée (souvent exanthématique), une <strong>éosinophilie</strong>, et une <strong>atteinte d'organes internes</strong> (foie, rein, poumons, cœur) se traduisant par des symptômes systémiques.</p><p>Les médicaments inducteurs fréquents sont les <strong>anticonvulsivants</strong>, les <strong>sulfamides</strong>, la <strong>minocycline</strong>, l'<strong>allopurinol</strong>, les <strong>IPP</strong> et les <strong>PCI</strong>. La mortalité est de <strong>5 à 10%</strong> et la régression est lente après l'arrêt du traitement.</p>"},{"i":"c52e83b37e0d","n":115,"o":"115-9","u":"Diagnostic positif","t":"Connaître les différents types de lésions cutanées induites par un médicament","q":"Quelle est la définition clinique d'un exanthème maculo-papuleux (EMP) induit par un médicament et quels sont les médicaments fréquemment impliqués ?","a":"<p>L'exanthème maculo-papuleux est une éruption cutanée survenant entre <strong>4 et 14 jours</strong> après l'introduction d'un médicament (classiquement 8-10 jours). Il se caractérise par des <strong>maculo-papules rouges</strong>, parfois confluentes en plaques, mais avec des <strong>espaces de peau saine</strong>.</p><p>Les médicaments fréquemment impliqués sont les <strong>aminopénicillines</strong>, les <strong>bêtalactamines</strong>, les <strong>sulfamides antibactériens</strong>, les <strong>antituberculeux</strong> et les <strong>antimitotiques</strong>.</p>"},{"i":"c5fc1112cb19","n":115,"o":"115-9","u":"Diagnostic positif","t":"Connaître les différents types de lésions cutanées induites par un médicament","q":"Comment se manifeste une pustulose exanthématique aiguë généralisée (PEAG) médicamenteuse et quels en sont les signes d'orientation diagnostique ?","a":"<p>La PEAG est une toxidermie qui débute généralement de façon <strong>brutale et très fébrile</strong> (fièvre élevée) entre <strong>1 et 11 jours</strong> après l'administration d'un traitement. Elle se caractérise par un <strong>érythème en nappe scarlatiniforme</strong>, rapidement suivi par l'apparition de <strong>nombreuses pustules amicrobiennes superficielles</strong> (< 2 mm) à contenu lactescent, prédominant dans les <strong>grands plis</strong> (aisselles, aines).</p><p>Les signes d'orientation comprennent une <strong>hyperpolynucléose neutrophile</strong> à la biologie et une biopsie cutanée montrant une accumulation de <strong>PNN dans la partie superficielle de l'épiderme</strong> (pustules sous-cornées).</p>"},{"i":"ebc01390d011","n":115,"o":"115-9","u":"Diagnostic positif","t":"Connaître les différents types de lésions cutanées induites par un médicament","q":"Quelles sont les caractéristiques principales de l'érythème pigmenté fixe (EPF) induit par un médicament ?","a":"<p>L'érythème pigmenté fixe est une toxidermie caractérisée par des <strong>macules érythémateuses arrondies</strong>, souvent douloureuses et infiltrées, qui apparaissent en <strong>quelques heures à 2 jours</strong> après la prise du médicament. Elles siègent préférentiellement au niveau des <strong>organes génitaux externes</strong> et des <strong>lèvres</strong>.</p><p>Les médicaments classiquement impliqués sont le <strong>paracétamol</strong> et les <strong>AINS</strong>. Une réintroduction du médicament entraîne une récidive rapide aux <strong>mêmes sites</strong>, laissant des taches pigmentées résiduelles.</p>"},{"i":"fa29d7a0b9a4","n":115,"o":"115-9","u":"Diagnostic positif","t":"Connaître les différents types de lésions cutanées induites par un médicament","q":"Quelles toxidermies médicamenteuses s'inscrivent dans le spectre des Stevens-Johnson / Lyell-NET et quelles sont leurs caractéristiques principales ?","a":"<p>Le syndrome de Stevens-Johnson (SJS) et la nécrolyse épidermique toxique (NET ou syndrome de Lyell) représentent des formes graves de toxidermies classées sous un même spectre. Elles débutent généralement entre <strong>4 et 28 jours</strong> après l'exposition médicamenteuse et se caractérisent par un <strong>décollement épidermique aigu</strong>.</p><p>Les SJS/NET sont associées à une mortalité élevée (<strong>20-25%</strong>). Les médicaments fréquemment impliqués incluent les <strong>sulfamides antibactériens</strong>, les <strong>anticonvulsivants</strong>, les <strong>AINS</strong> (notamment les oxicams), l'<strong>allopurinol</strong> et la <strong>névirapine</strong>.</p>"}]};